function auth(register=false){modal(`<div class="eyebrow">YOUR DEPARTMENT WORKSPACE</div><h2>${register?'Create your account':'Welcome back.'}</h2><p class="muted">Sign in to save and reopen your plans.</p><form id="auth">${register?'<label>Your name<input name="name" required autocomplete="name"></label><label>Department<input name="department" required></label>':''}<label>Email<input name="email" type="email" required autocomplete="email"></label><label>Password<input name="password" type="password" required minlength="10" autocomplete="${register?'new-password':'current-password'}"></label><p id="auth-error" class="error"></p><button class="primary">${register?'Create account':'Sign in'}</button></form><button class="link" id="switch-auth">${register?'Already have an account? Sign in':'New here? Create an account'}</button>`);$('#switch-auth').onclick=()=>auth(!register);$('#auth').onsubmit=async e=>{e.preventDefault();try{user=await api(register?'register':'login','POST',Object.fromEntries(new FormData(e.target)));$('#modal').close();account();toast('Signed in. Your workspace is ready.')}catch(e){$('#auth-error').textContent=e.message}}}
function account(){$('#account').textContent=user?user.name:'Sign in'}
$('#account').onclick=()=>{if(!user)return auth();modal(`<h2>${esc(user.name)}</h2><p>${esc(user.email)}</p>${user.role==='admin'?'<button id="admin">Manage users</button>':''}<button id="logout">Sign out</button>`);$('#logout').onclick=async()=>{await api('logout','POST');user=null;account();$('#modal').close();projectId=null;toast('Signed out')};if($('#admin'))$('#admin').onclick=admin};
async function admin(){try{const users=await api('users');modal('<h2>User management</h2><p class="muted">Suspension blocks all backend access immediately.</p>'+users.map(u=>`<div class="project-row"><div>${esc(u.name)}<small>${esc(u.email)} · ${esc(u.status)}</small></div>${u.id!==user.id?`<button data-user="${u.id}" data-status="${u.status==='active'?'suspended':'active'}">${u.status==='active'?'Suspend':'Activate'}</button>`:''}</div>`).join(''));document.querySelectorAll('[data-user]').forEach(b=>b.onclick=async()=>{try{await api('users','PUT',{id:b.dataset.user,status:b.dataset.status});admin()}catch(e){toast(e.message)}})}catch(e){toast(e.message)}}
function remember(){history.push(JSON.stringify(state));if(history.length>60)history.shift();future=[];mark()}
function mark(){dirty=true;$('#save-status').textContent='Unsaved changes'}
function restore(s){state=JSON.parse(s);selected=-1;pending=[];$('#units').value=state.units;mark();render()}
$('#undo').onclick=()=>{if(history.length){future.push(JSON.stringify(state));restore(history.pop())}};$('#redo').onclick=()=>{if(future.length){history.push(JSON.stringify(state));restore(future.pop())}};
function library(){let category='';$('#symbols').innerHTML=symbols.filter(s=>(s.join(' ')+' '+symbolReference(s[0]).note).toLowerCase().includes($('#search').value.toLowerCase())).map(s=>{const heading=s[2]!==category?`<div class="category">${s[2].toUpperCase()}</div>`:'';category=s[2];return heading+`<button class="symbol" data-code="${s[0]}" title="${esc(symbolReference(s[0]).note)}">${symbolThumb(s[0])}<span>${esc(s[1])}</span></button>`}).join('');document.querySelectorAll('[data-code]').forEach(b=>b.onclick=()=>setTool('symbol:'+b.dataset.code))}
$('#search').oninput=library;library();
$('#symbol-reference').onclick=()=>modal(`<div class="eyebrow">SYMBOL LIBRARY REFERENCE</div><h2>NFPA 170 · 2024</h2><p>Symbols for Use by the Fire Service · Table 5.2</p><p>17 SVG reproductions traced from your supplied pages 170-15 through 170-17. Colors and field shapes follow the Characteristics column. Descriptions summarize the Application column.</p><p>Directional-arrow backgrounds should match their accompanying sign; select an arrow to choose its background.</p><p class="muted">Screen colors are digital approximations, not certified safety-color specifications. Supplemental abbreviations remain available separately.</p><p><a href="${nfpaSource}" target="_blank" rel="noopener noreferrer">NFPA 170 · 2024 ↗</a></p>`);

function setTool(t){if((t==='distance'||t==='area')&&!state.scale){toast('Set the scale using a known distance first.');t='calibrate'}tool=t;pending=[];document.querySelectorAll('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===t));$('#hint').textContent=({select:'Select and drag a symbol. Drag empty space to pan.',calibrate:'Choose two points with a known distance.',distance:'Choose two points to measure their distance.',area:'Click boundary points. Double-click to finish the area.',text:'Click the plan to add a label.'})[t]||symbolReference(t.split(':')[1]).note;render()}
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));
function example(){ctx.fillStyle='#fcfcf8';ctx.fillRect(0,0,1600,1000);ctx.fillStyle='#eef1e9';ctx.fillRect(90,75,1420,820);ctx.strokeStyle='#cdd5c9';ctx.lineWidth=2;for(let x=170;x<1450;x+=100){ctx.strokeRect(x,820,70,65)}ctx.fillStyle='#fbfaf3';ctx.fillRect(310,230,900,510);ctx.strokeStyle='#778472';ctx.lineWidth=9;ctx.strokeRect(310,230,900,510);ctx.beginPath();ctx.moveTo(790,230);ctx.lineTo(790,740);ctx.moveTo(310,465);ctx.lineTo(790,465);ctx.moveTo(790,490);ctx.lineTo(1210,490);ctx.moveTo(1000,230);ctx.lineTo(1000,490);ctx.moveTo(790,600);ctx.lineTo(1210,600);ctx.stroke();ctx.fillStyle='#e8eddf';for(let x=360;x<720;x+=150){ctx.fillRect(x,280,90,135);ctx.fillRect(x,520,90,135)}ctx.fillStyle='#7c8875';ctx.textAlign='center';ctx.font='17px sans-serif';[['APPARATUS BAY',550,445],['EQUIPMENT / STORAGE',550,700],['OFFICE',890,370],['CREW ROOM',1100,370],['CORRIDOR',1000,559],['LOBBY',1000,690]].forEach(([t,x,y])=>ctx.fillText(t,x,y));ctx.fillStyle='#fcfcf8';ctx.fillRect(1090,733,85,15);ctx.strokeStyle='#a8b29e';ctx.lineWidth=2;ctx.beginPath();ctx.arc(1090,735,85,-Math.PI/2,0);ctx.moveTo(1090,735);ctx.lineTo(1090,650);ctx.stroke();ctx.fillStyle='#87947c';ctx.font='13px sans-serif';ctx.fillText('TRAINING EXAMPLE · NOT AN OPERATIONAL PLAN',800,140);ctx.fillText('APPARATUS ACCESS',800,930);ctx.font='bold 22px sans-serif';ctx.fillText('N ↑',1400,170)}
function distance(a,b){return Math.hypot(a.x-b.x,a.y-b.y)*state.scale}
function area(points){return Math.abs(points.reduce((n,p,i)=>{let q=points[(i+1)%points.length];return n+p.x*q.y-q.x*p.y},0))/2*state.scale**2}
function draw(clean=false){canvas.width=state.width;canvas.height=state.height;ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);if(base)ctx.drawImage(base,0,0,state.width,state.height);else example();state.items.forEach((it,i)=>{ctx.save();if(it.type==='symbol'){const art=symbolImage(it.code,it.background);if(art?.complete&&art.naturalWidth){const height=56,width=height*art.naturalWidth/art.naturalHeight;ctx.drawImage(art,it.x-width/2,it.y-height/2,width,height)}else{const s=symbols.find(s=>s[0]===it.code);ctx.fillStyle='white';ctx.strokeStyle=s?.[3]||'#254e3d';ctx.lineWidth=3;ctx.beginPath();ctx.roundRect(it.x-28,it.y-25,56,50,7);ctx.fill();ctx.stroke();ctx.fillStyle=s?.[3]||'#254e3d';ctx.font='bold '+(it.code.length>4?10:14)+'px sans-serif';ctx.textAlign='center';ctx.fillText(it.code,it.x,it.y+5);}if(it.label!==it.code)label(it.label,it.x,it.y+44)}else if(it.type==='text'){label(it.label,it.x,it.y)}else{const pts=it.points;ctx.strokeStyle='#297b85';ctx.fillStyle='#297b851a';ctx.lineWidth=3;ctx.beginPath();pts.forEach((p,j)=>j?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));if(it.type==='area'){ctx.closePath();ctx.fill()}ctx.stroke();pts.forEach(p=>{ctx.beginPath();ctx.arc(p.x,p.y,5,0,Math.PI*2);ctx.fillStyle='#297b85';ctx.fill()});const mid={x:pts.reduce((n,p)=>n+p.x,0)/pts.length,y:pts.reduce((n,p)=>n+p.y,0)/pts.length};label(it.type==='area'?`${area(pts).toFixed(1)} ${state.units}²`:`${distance(pts[0],pts[1]).toFixed(1)} ${state.units}`,mid.x,mid.y-12)}if(!clean&&i===selected){const p=it.points?it.points[0]:it;ctx.strokeStyle='#244e3d';ctx.setLineDash([5,4]);ctx.strokeRect(p.x-35,p.y-33,70,66)}ctx.restore()});if(!clean&&pending.length){ctx.fillStyle='#297b85';pending.forEach(p=>{ctx.beginPath();ctx.arc(p.x,p.y,6,0,Math.PI*2);ctx.fill()})}}
function label(t,x,y){ctx.font='bold 16px sans-serif';ctx.textAlign='center';const w=ctx.measureText(t).width;ctx.fillStyle='#fffffff0';ctx.fillRect(x-w/2-8,y-19,w+16,27);ctx.fillStyle='#294435';ctx.fillText(t,x,y)}
let pan={x:0,y:0};function fit(){zoom=1;pan={x:0,y:0};layout()}function layout(){const box=$('.canvas-wrap');let ratio=Math.min((box.clientWidth-90)/state.width,(box.clientHeight-140)/state.height)*zoom;canvas.style.width=state.width*ratio+'px';canvas.style.height=state.height*ratio+'px';canvas.style.left=(box.clientWidth-state.width*ratio)/2+pan.x+'px';canvas.style.top=(box.clientHeight-state.height*ratio)/2+pan.y+'px';$('#zoom-value').textContent=Math.round(zoom*100)+'%'}
function legendSymbols(){return [...new Map(state.items.filter(i=>i.type==='symbol').map(i=>[i.code+(i.background||''),{code:i.code,background:i.background}])).values()]}
function render(){draw();layout();$('#scale-status').textContent=state.scale?`${state.scale.toFixed(4)} ${state.units} / px`:'Scale not calibrated';$('#count').textContent=state.items.filter(i=>i.type==='symbol').length+' symbols';const codes=legendSymbols();$('#legend').innerHTML=codes.map(({code,background})=>{const s=symbols.find(s=>s[0]===code);return `<div class="legend-row">${symbolThumb(code,background)}${esc(s?.[1]||code)}</div>`}).join('')||'<p class="muted">No symbols placed yet.</p>';inspector()}
function inspector(){const it=state.items[selected];$('#selection').innerHTML=it?`<span class="eyebrow">SELECTED ${esc(it.type.toUpperCase())}</span>${it.label!==undefined?`<input id="item-label" aria-label="Selected item label" value="${esc(it.label)}">`:''}${it.type==='symbol'?`<p class="symbol-reference-label">${esc(symbolReference(it.code).section)}</p><p>${esc(symbolReference(it.code).note)}</p>${symbolDefinition(it.code)?`<div class="selected-art">${symbolThumb(it.code,it.background)}</div><p class="muted">${esc(symbolDefinition(it.code).characteristics.field)} field · SVG artwork</p>`:''}${it.code.startsWith('ARROW')?`<label>Match accompanying sign<select id="arrow-background">${Object.entries(arrowColors).map(([name,color])=>`<option value="${color}" ${(it.background||'#C8102E')===color?'selected':''}>${name}</option>`).join('')}</select></label>`:''}`:''}<button id="delete">Delete element</button>`:'<span class="eyebrow">SELECTION</span><p>Select a symbol or annotation to edit its label or remove it.</p>';if($('#arrow-background'))$('#arrow-background').onchange=e=>{remember();it.background=e.target.value;render()};if($('#delete'))$('#delete').onclick=remove;if($('#item-label'))$('#item-label').onchange=e=>{remember();it.label=e.target.value.slice(0,80);render()}}
function remove(){if(selected<0)return;remember();state.items.splice(selected,1);selected=-1;render()}
function point(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*state.width/r.width,y:(e.clientY-r.top)*state.height/r.height}}
canvas.onpointerdown=e=>{const p=point(e);if(tool==='select'){selected=state.items.findLastIndex(it=>it.points?it.points.some(q=>Math.hypot(q.x-p.x,q.y-p.y)<35):Math.hypot(it.x-p.x,it.y-p.y)<40);if(selected>=0&&!state.items[selected].points){remember();drag={type:'item',dx:state.items[selected].x-p.x,dy:state.items[selected].y-p.y}}else if(selected<0){drag={type:'pan',x:e.clientX,y:e.clientY,px:pan.x,py:pan.y}}canvas.setPointerCapture(e.pointerId);render();return}if(tool.startsWith('symbol:')){remember();const code=tool.split(':')[1];state.items.push({type:'symbol',code,label:code,...p});selected=state.items.length-1;render();return}if(tool==='text'){const text=prompt('Label text');if(text){remember();state.items.push({type:'text',label:text.slice(0,80),...p});render()}return}if(e.detail===2)return;pending.push(p);if(tool==='area'){render();return}if(pending.length===2){if(tool==='calibrate'){const pixels=Math.hypot(pending[0].x-p.x,pending[0].y-p.y);const value=Number(prompt(`Known distance in ${state.units}:`));if(value>0&&Number.isFinite(value)&&pixels>1){remember();state.scale=value/pixels;toast('Measurement scale updated.')}}else{remember();state.items.push({type:'distance',points:[...pending]})}pending=[]}render()};
canvas.onpointermove=e=>{if(!drag)return;if(drag.type==='pan'){pan={x:drag.px+e.clientX-drag.x,y:drag.py+e.clientY-drag.y};layout()}else{const p=point(e),it=state.items[selected];it.x=Math.max(30,Math.min(state.width-30,p.x+drag.dx));it.y=Math.max(30,Math.min(state.height-30,p.y+drag.dy));draw()}};canvas.onpointerup=()=>drag=null;canvas.onpointercancel=()=>drag=null;canvas.ondblclick=()=>{if(tool==='area'&&pending.length>=3){remember();state.items.push({type:'area',points:[...pending]});pending=[];render()}};
$('#zoom-in').onclick=()=>{zoom=Math.min(4,zoom+.25);layout()};$('#zoom-out').onclick=()=>{zoom=Math.max(.5,zoom-.25);layout()};$('#fit').onclick=fit;window.onresize=layout;
$('#units').onchange=e=>{remember();if(state.scale)state.scale*=e.target.value==='m'?.3048:1/.3048;state.units=e.target.value;render()};$('#title').oninput=mark;
$('#upload').onclick=$('#replace').onclick=()=>{if(!user)return auth();$('#file').click()};
async function loadBase(){base=null;if(state.asset){base=new Image();base.src='/api/assets/'+state.asset;await base.decode()}$('#base-name').textContent=state.asset?'Uploaded plan':'Training floor plan';$('#view-name').textContent=state.asset?'UPLOADED PLAN':'GROUND FLOOR / TRAINING EXAMPLE';$('#subtitle').textContent=state.asset?'Private base image · Editable project':'Training example · Replace with your floor or site plan'}
$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024||!['image/png','image/jpeg'].includes(file.type))throw Error('Choose a PNG or JPEG under 10 MB.');if(state.items.length&&!confirm('Replace the base and clear its symbols, measurements, and calibration?'))return;const url=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});const img=new Image();img.src=url;await img.decode();if(img.width>8000||img.height>8000||img.width*img.height>24000000)throw Error('Image is too large. Use at most 24 megapixels and 8000 pixels per side.');const a=await api('assets','POST',{mime:file.type,data:url.split(',')[1]});state={asset:a.id,width:img.width,height:img.height,scale:null,units:state.units,items:[]};history=[];future=[];selected=-1;pending=[];await loadBase();mark();fit();setTool('calibrate');render();toast('Image uploaded. Set its measurement scale.')}catch(e){toast(e.message)}finally{$('#file').value=''}};
$('#save').onclick=async()=>{if(!user)return auth();try{const result=await api('projects','POST',{id:projectId,title:$('#title').value||'Untitled plan',state:{...state,symbolStandard}});projectId=result.id;dirty=false;$('#save-status').textContent='Saved just now';toast('Project saved to the database.')}catch(e){toast(e.message)}};
$('#projects').onclick=async()=>{if(!user)return auth();try{const projects=await api('projects');modal('<h2>Your saved projects</h2><p class="muted">Private plans, ready to pick up where you left off.</p><button id="new-project">＋ New project</button>'+projects.map(p=>`<div class="project-row"><div>${esc(p.title)}<small>${new Date(p.updated*1000).toLocaleString()}</small></div><button data-project="${p.id}">Open ↗</button></div>`).join(''));$('#new-project').onclick=()=>{if(dirty&&!confirm('Discard unsaved changes?'))return;projectId=null;state={asset:null,width:1600,height:1000,scale:null,units:'ft',items:[]};base=null;history=[];future=[];selected=-1;$('#title').value='Untitled plan';$('#modal').close();mark();loadBase();fit();render()};document.querySelectorAll('[data-project]').forEach(b=>b.onclick=async()=>{if(dirty&&!confirm('Discard unsaved changes and open this project?'))return;try{const p=await api('projects/'+b.dataset.project);state=p.state;projectId=p.id;$('#title').value=p.title;$('#units').value=state.units;await loadBase();history=[];future=[];selected=-1;pending=[];dirty=false;$('#save-status').textContent='Saved project';$('#modal').close();fit();render()}catch(e){toast(e.message)}})}catch(e){toast(e.message)}};
function exportCanvas(){draw(true);const used=legendSymbols();const out=document.createElement('canvas');out.width=Math.max(1000,state.width);const cols=Math.max(1,Math.floor((out.width-60)/460)),rows=Math.ceil(used.length/cols);out.height=state.height+170+rows*68;const c=out.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,out.width,out.height);c.drawImage(canvas,(out.width-state.width)/2,80);c.fillStyle='#244e3d';c.font='bold 25px sans-serif';c.fillText($('#title').value,30,43,out.width-60);c.font='14px sans-serif';c.fillText('Approximate planning information · '+new Date().toLocaleDateString(),30,state.height+115);used.forEach(({code,background},i)=>{const s=symbols.find(s=>s[0]===code),x=30+(i%cols)*((out.width-60)/cols),y=state.height+145+Math.floor(i/cols)*68,art=symbolImage(code,background);if(art?.complete&&art.naturalWidth)c.drawImage(art,x,y,42*art.naturalWidth/art.naturalHeight,42);else{c.font='bold 10px sans-serif';c.fillText(code,x,y+22)}c.font='12px sans-serif';const words=(s?.[1]||code).split(' ');let line='',ly=y+14;for(const word of words){if(c.measureText(line+word).width>360){c.fillText(line,x+52,ly);ly+=15;line=''}line+=word+' '}c.fillText(line,x+52,ly)});draw();return out}

function download(blob,ext){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=($('#title').value.replace(/[^a-z0-9 -]/gi,'')||'plan')+'.'+ext;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function pdf(out){const binary=atob(out.toDataURL('image/jpeg',.94).split(',')[1]),jpeg=Uint8Array.from(binary,c=>c.charCodeAt(0)),encoder=new TextEncoder();let parts=[],offset=0,offsets=[0];const add=v=>{const b=typeof v==='string'?encoder.encode(v):v;parts.push(b);offset+=b.length};const obj=(n,s)=>{offsets[n]=offset;add(`${n} 0 obj\n${s}\nendobj\n`)};add('%PDF-1.4\n');const w=792,h=612,ratio=Math.min((w-40)/out.width,(h-40)/out.height),iw=out.width*ratio,ih=out.height*ratio;obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,'<< /Type /Pages /Kids [3 0 R] /Count 1 >>');obj(3,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${w} ${h}] /Resources << /XObject << /Im0 4 0 R >> >> /Contents 5 0 R >>`);offsets[4]=offset;add(`4 0 obj\n<< /Type /XObject /Subtype /Image /Width ${out.width} /Height ${out.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpeg.length} >>\nstream\n`);add(jpeg);add('\nendstream\nendobj\n');const stream=`q ${iw} 0 0 ${ih} ${(w-iw)/2} ${(h-ih)/2} cm /Im0 Do Q`;obj(5,`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`);const start=offset;add('xref\n0 6\n0000000000 65535 f \n');for(let i=1;i<=5;i++)add(String(offsets[i]).padStart(10,'0')+' 00000 n \n');add(`trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${start}\n%%EOF`);return new Blob(parts,{type:'application/pdf'})}
$('#export').onclick=()=>{modal('<div class="eyebrow">TAKE YOUR PLAN WITH YOU</div><h2>Export your plan</h2><p class="muted">Includes the base image, symbols, measurements, title, and legend. PDF uses a landscape letter page.</p><button class="primary" id="png">Download PNG</button><button class="primary" id="pdf">Download PDF</button><p class="muted">Emergency Networking compatibility has not yet been verified.</p>');$('#png').onclick=async()=>{try{await symbolsReady;exportCanvas().toBlob(b=>download(b,'png'),'image/png')}catch(e){toast('Symbol artwork failed to load. Reload before exporting.')}};$('#pdf').onclick=async()=>{try{await symbolsReady;download(pdf(exportCanvas()),'pdf')}catch(e){toast('Symbol artwork failed to load. Reload before exporting.')}}};
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.key==='Escape'){pending=[];setTool('select')}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();remove()}if((e.ctrlKey||e.metaKey)&&e.key==='z'){e.preventDefault();$(e.shiftKey?'#redo':'#undo').click()}});window.onbeforeunload=e=>{if(dirty){e.preventDefault();e.returnValue=''}};
api('me').then(u=>{user=u;account()}).catch(()=>{});render();

symbolsReady.then(()=>render()).catch(()=>toast("Symbol artwork failed to load. Please reload before exporting."));
